package cn.xi.cloudwidget;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;

public class PolishChecks extends WaterChecks {
    @Override public void onStart(){if(!"polish".equals(args.getString("phase"))){super.onStart();return;}Bundle result=new Bundle();try{c=getTargetContext();Store store=new Store(c);String blue=Backup.prefs(c).getString("card:qa034-preupgrade-0",null),green=Backup.prefs(c).getString("card:qa034-preupgrade-1",null),serif=Backup.prefs(c).getString("card:qa034-preupgrade-2",null);check(new JSONObject(blue).getInt("borderInk")==0xffdce9f3&&new JSONObject(green).getInt("borderInk")==0xffdfe9dc,"real v033 pre-upgrade border fixtures retain both original colors");JSONObject old=new JSONObject(serif);old.put("id","qa034-legacy-editor-copy");Backup.prefs(c).edit().putString("card:qa034-legacy-editor-copy",old.toString()).commit();EditorActivity legacy=(EditorActivity)startActivitySync(new Intent(c,PortraitEditorActivity.class).putExtra("card","qa034-legacy-editor-copy").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Card card=(Card)field("card").get(legacy);check(card.font==3&&Renderer.font(c,card.font)==Typeface.DEFAULT,"old font-3 card opens and renders with system fallback");main(()->{try{field("tab").setInt(legacy,2);legacy.showPanel();}catch(Exception error){throw new RuntimeException(error);}});check(find(legacy.getWindow().getDecorView(),"字体：思源宋体")==null,"removed Serif does not appear in the native selector");for(int id:new int[]{0,1,2,4,5,6})check(find(legacy.getWindow().getDecorView(),"字体："+Card.FONTS[id])!=null,"native selector keeps stable font ID "+id);check(named(legacy.getWindow().getDecorView(),"思源宋体已移除，当前使用系统默认；保存时更新为系统默认。")!=null,"editor explains the removed font without silently choosing another family");main(legacy::save);check(store.get(card.id).font==0,"explicit Save migrates only that old font card to ID zero");check(Backup.prefs(c).getString("card:qa034-preupgrade-2","").equals(serif),"opening and saving a QA copy leaves the actual pre-upgrade font-3 original untouched");
        EditorActivity editor=(EditorActivity)startActivitySync(new Intent(c,PortraitEditorActivity.class).putExtra("card","qa034-water-linked").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Card water=(Card)field("card").get(editor);String history=water.waterHistory.toString();main(()->named(editor.getWindow().getDecorView(),"自定义常用加水量").performClick());AlertDialog dialog=(AlertDialog)field("waterNumberDialog").get(editor);EditText input=editText(dialog.getWindow().getDecorView());for(String bad:new String[]{"0","-1","3001","1.5"}){main(()->{input.setText(bad);dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});check(dialog.isShowing()&&water.waterQuickMl==250,"invalid custom quick amount is not saved: "+bad);}main(()->{input.setText("300");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});main(editor::save);check(store.get(water.id).waterQuickMl==300&&store.get(water.id).waterHistory.toString().equals(history),"custom common amount persists without altering water records");
        WaterHostActivity host=(WaterHostActivity)startActivitySync(new Intent(c,WaterHostActivity.class).putExtra("reuse",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();WaterAddActivity sheet=open(host,0);check(sheet.amount.getText().toString().equals("300")&&named(sheet.getWindow().getDecorView(),"+300")!=null,"lightweight record page uses the custom common amount");close(sheet);
        EditorActivity border=(EditorActivity)startActivitySync(new Intent(c,PortraitEditorActivity.class).putExtra("card","qa034-preupgrade-0").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();main(()->{try{field("tab").setInt(border,3);border.showPanel();}catch(Exception error){throw new RuntimeException(error);}});check(find(border.getWindow().getDecorView(),"边框颜色 #9FBDD0")!=null&&find(border.getWindow().getDecorView(),"边框颜色 #A8C3A5")!=null,"only border palette exposes the stronger blue and green presets");check(((Card)field("card").get(border)).borderInk==0xffdce9f3,"opening a legacy border card does not migrate its saved old color");main(border::finish);check(Backup.prefs(c).getString("card:qa034-preupgrade-0","").equals(blue)&&Backup.prefs(c).getString("card:qa034-preupgrade-1","").equals(green),"both pre-upgrade border JSON records remain unchanged after editor inspection");check(Controls.borderBackdrop(-1)!=Controls.borderBackdrop(0xff111111),"white-border thumbnail contrast backing remains adaptive");
        startActivitySync(new Intent(c,PolishQAActivity.class).putExtra("mode","icons").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));result.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){result.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
